        Op::SubgroupFence { .. } => [1, 9],
        Op::Atomic { .. } => [1, 10],
        Op::WorkgroupCollective { .. } => [1, 11],
        Op::SubgroupCollective { .. } => [1, 12],
        Op::MatrixAccess { .. } => [1, 13],
        Op::AsyncCopy { .. } => [1, 14],
        Op::AsyncWait { .. } => [1, 15],
        Op::RawMemoryBind { .. } => [1, 16],
        Op::PrivateMemoryAllocate { .. } => [1, 17],
        Op::WorkgroupMemoryIndex { .. } => [1, 18],
